I left out both operations requests. The node's `with` clause grants only `aap:caps/notifier@0.1.0`, so it has no filesystem access for the log file and no HTTP capability for the metadata service. Adding either would mean importing interfaces the node isn't granted. The node only notifies and reports whether the notification was accepted.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut message = String::new();
        message.push_str(&composed.date);
        message.push('\n');
        message.push_str(&composed.overview);
        for e in &composed.entries {
            if e.kept {
                message.push('\n');
                message.push_str(&e.title);
                message.push_str(" - ");
                message.push_str(&e.link);
                message.push_str("\n  ");
                message.push_str(&e.summary);
            }
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
